  <a hlmBtn variant="ghost" routerLink="/roster" class="hero-detail__back">
    <ng-icon name="lucideChevronLeft" />
    Back to roster
  </a>

  @if (vm.hero(); as hero) {
    <header class="hero-detail__header">
      <div class="hero-detail__identity">
        <hlm-avatar size="lg">
          <span hlmAvatarFallback>{{ vm.initials() }}</span>
        </hlm-avatar>
        <div class="hero-detail__names">
          <h1 class="hero-detail__title">{{ hero.name }}</h1>
          <p class="hero-detail__alias">{{ hero.alias }} · {{ hero.id }}</p>
          <div class="hero-detail__badges">
            <span hlmBadge variant="outline">{{ hero.powerClass }}</span>
            <span hlmBadge [variant]="vm.statusVariant()">{{ hero.status }}</span>
          </div>
        </div>
      </div>

      <div class="hero-detail__actions">
        <button hlmBtn [disabled]="!vm.canDeploy()" (click)="vm.deploy()">
          <ng-icon name="lucideCrosshair" />
          Deploy
        </button>

        <hlm-dialog #retireDialog>
          <button hlmBtn variant="destructive" hlmDialogTrigger>
            <ng-icon name="lucideTrash2" />
            Retire
