              </p>
            </hlm-dialog-header>
            <hlm-dialog-footer>
              <button hlmBtn variant="outline" hlmDialogClose>Cancel</button>
              <button hlmBtn variant="destructive" (click)="vm.retire(); retireDialog.close()">Retire hero</button>
