/* You can add global styles to this file, and also import other style files */

/*
 * Hero Ops Console palette. Each role from the capstone build spec is mapped
 * onto a spartan token; the semantic colours (success, warning, info) have no
 * spartan equivalent and are declared alongside them. Values are six-digit hex
 * so `npm run check:contrast` can read and vouch for every pair.
 */
:root {
  color-scheme: light;

  --font-sans:
    -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, 'Noto Sans',
    sans-serif, 'Apple Color Emoji', 'Segoe UI Emoji', 'Segoe UI Symbol', 'Noto Color Emoji';

  --chart-1: #d8891a;
  --chart-2: #4f7cf0;
  --chart-3: #2fb574;
  --chart-4: #e4802b;
  --chart-5: #e5484d;
  --radius: 0.625rem;
  --background: #f6f7fa;
  --foreground: #1b1e2b;
  --card: #ffffff;
  --card-foreground: #1b1e2b;
  --popover: #ffffff;
  --popover-foreground: #1b1e2b;
  --primary: #d8891a;
  --primary-foreground: #241a05;
  --secondary: #eef0f6;
  --secondary-foreground: #1b1e2b;
  --muted: #eef0f6;
  --muted-foreground: #5b6072;
  --accent: #eef0f6;
  --accent-foreground: #1b1e2b;
  --destructive: #e5484d;
  --destructive-foreground: #000000;
  --border: #e4e7ef;
  --input: #e4e7ef;
  --ring: #b06a0c;

  --success: #2fb574;
  --warning: #e4802b;
  --info: #4f7cf0;

  /* The navigation rail is dark in both themes. */
  --sidebar: #1e2233;
  --sidebar-foreground: #eceef6;
  --sidebar-primary: #d8891a;
  --sidebar-primary-foreground: #241a05;
  --sidebar-accent: #2a2f45;
  --sidebar-accent-foreground: #eceef6;
  --sidebar-muted: #9aa0b4;
  --sidebar-border: #2a2f45;
  --sidebar-ring: #d8891a;
}

:root.dark {
  color-scheme: dark;

  --chart-1: #f5b843;
  --chart-2: #6f97f6;
  --chart-3: #3ecb84;
  --chart-4: #f0983f;
  --chart-5: #f2585d;
  --background: #0e1018;
  --foreground: #eceef6;
  --card: #171a26;
  --card-foreground: #eceef6;
  --popover: #171a26;
  --popover-foreground: #eceef6;
  --primary: #f5b843;
  --primary-foreground: #241a05;
  --secondary: #1e2231;

