1	import { Injectable, computed, inject, linkedSignal, signal } from '@angular/core';
2	import { toSignal } from '@angular/core/rxjs-interop';
3	import { form, validateStandardSchema } from '@angular/forms/signals';
4	import { ActivatedRoute, Router } from '@angular/router';
5	import { map } from 'rxjs';
6	import { HeroService } from '../domain/hero.service';
7	import { POWER_CLASSES, type Hero } from '../domain/hero.model';
8	import { formMeta } from '../forms/zod-meta';
9	import { initialsOf, STATUS_BADGE, type BadgeVariant } from '../ui/hero-badges';
10	import { heroSchema, type HeroModel } from './hero-detail.schema';
11	
12	/** The edit form's model for a hero, or blank values while no hero matches the id. */
13	function modelOf(hero: Hero | undefined): HeroModel {
14	  return {
15	    name: hero?.name ?? '',
16	    alias: hero?.alias ?? '',
17	    powerClass: hero?.powerClass ?? POWER_CLASSES[0],
18	    powerIndex: hero?.powerIndex ?? 0,
19	    status: hero?.status ?? 'Active',
20	  };
21	}
22	
23	/**
24	 * The hero detail screen's state: the hero named by the `detail/:id` route, the
25	 * edit form built from the zod schema, and the deploy and retire actions.
26	 */
27	@Injectable()
28	export class HeroDetailViewModel {
29	  private readonly heroService = inject(HeroService);
30	  private readonly router = inject(Router);
31	
32	  /** The route's `:id`. Reading paramMap (not the snapshot) keeps it current when only the id changes. */
33	  private readonly heroId = toSignal(
34	    inject(ActivatedRoute).paramMap.pipe(map((params) => params.get('id') ?? '')),
35	    { initialValue: '' },
36	  );
37	
38	  /** The hero the route names, or undefined when no hero on the roster has that id. */
39	  readonly hero = computed<Hero | undefined>(() => this.heroService.find(this.heroId()));
40	
41	  /** Two-letter monogram for the header avatar. */
42	  readonly initials = computed(() => initialsOf(this.hero()?.alias ?? ''));
43	
44	  readonly statusVariant = computed<BadgeVariant>(() => {
45	    const status = this.hero()?.status;
46	    return status ? STATUS_BADGE[status] : 'secondary';
47	  });
48	
49	  /** Missions read as a rate: strong, shaky or failing. */
50	  readonly resultVariant = computed<BadgeVariant>(() => {
51	    const rate = this.hero()?.successRate ?? 0;
52	    if (rate >= 0.8) return 'success';
53	    return rate >= 0.5 ? 'warning' : 'destructive';
54	  });
55	
56	  readonly successLabel = computed(() => `${Math.round((this.hero()?.successRate ?? 0) * 100)}%`);
57	
58	  /** Only an Active hero can be deployed. */
59	  readonly canDeploy = computed(() => this.hero()?.status === 'Active');
60	
61	  /** The label and the options come off the schema, so the template restates neither. */
62	  readonly fields = formMeta(heroSchema);
63	  readonly powerClassOptions = this.fields.powerClass.options ?? [];
64	  readonly statusOptions = this.fields.status.options ?? [];
65	
66	  /** The form's model. Follows the hero: a new route or a saved edit resets it to the stored values. */
67	  private readonly model = linkedSignal<HeroModel>(() => modelOf(this.hero()));
68	
69	  /** The edit form. Validation runs through the schema; submit runs `commit`. */
70	  readonly heroForm = form(
71	    this.model,
72	    (path) => validateStandardSchema(path, heroSchema),
73	    { submission: { action: () => this.commit() } },
74	  );
75	
76	  /** A one-line status for the screen: save and deploy feedback. */
77	  readonly notice = signal('');
78	
79	  /** Write the edited values back to the roster. */
80	  private async commit(): Promise<void> {
81	    const hero = this.hero();
82	    if (!hero) return;
83	    const saved = this.heroService.update(hero.id, this.model());
84	    this.notice.set(saved ? `Saved ${saved.name}.` : '');
85	  }
86	
87	  /** Discard unsaved edits and show the stored values again. */
88	  reset(): void {
89	    this.model.set(modelOf(this.hero()));
90	    this.notice.set('');
91	  }
92	
93	  /** Set one of the two select-driven fields. The selects are not signal-forms controls, so they bind through here. */
94	  setField<K extends 'powerClass' | 'status'>(key: K, value: HeroModel[K] | null | undefined): void {
95	    if (value == null) return;
96	    this.model.update((current) => ({ ...current, [key]: value }));
97	  }
98	
99	  /** Deployment is not wired to missions yet; this files the order and says so. */
100	  deploy(): void {
101	    const hero = this.hero();
102	    if (!hero || !this.canDeploy()) return;
103	    this.notice.set(`Deployment order filed for ${hero.name}.`);
104	  }
105	
106	  /** Remove the hero from the roster and return to it. The dialog closes the confirm step. */
107	  retire(): void {
108	    const hero = this.hero();
109	    if (!hero) return;
110	    this.heroService.retire(hero.id);
111	    void this.router.navigateByUrl('/roster');
112	  }
113	}
114

