/** The icons a stat tile can show. Each one is registered below, so every name renders. */
export type StatTileIcon =
  | 'lucideUserCheck'
  | 'lucideActivity'
  | 'lucideZap'
  | 'lucideShieldAlert'
  | 'lucideTarget'
  | 'lucideCheck';

@Component({
  selector: 'app-stat-tile',
  imports: [NgIcon, HlmCardImports],
