// Scratch probe, outside the repo. Serves the built dist, runs the responsive
// gate's page check on every real route, then drives the write paths in a browser.
import { serveStatic, launchChromium } from 'file:///D:/Repos/angular-jig/harness/playwright/serve-and-visit.mjs';
import { assertResponsive } from 'file:///D:/Repos/angular-jig/harness/gate/check-responsive.mjs';

const DIST = 'D:/Repos/angular-jig/dist/angular-jig/browser';
const ROUTES = ['dashboard', 'roster', 'detail/HO-001', 'detail/HO-003', 'missions', 'threats', 'recruit', 'settings'];
const results = {};

const browser = await launchChromium();
const srv = await serveStatic(DIST, { spaFallback: true });
const O = srv.origin;

try {
  for (const route of ROUTES) {
    try {
      const { failures } = await assertResponsive({ origin: O, route, anchorSelector: 'app-root', browser });
      results[`responsive ${route}`] = failures.length ? JSON.stringify(failures).slice(0, 600) : 'ok';
    } catch (e) {
      results[`responsive ${route}`] = 'THREW ' + e.message.slice(0, 300);
    }
  }

  const context = await browser.newContext({ viewport: { width: 1280, height: 900 } });
  const page = await context.newPage();
  const errors = [];
  page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
  page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });

  const nav = (name) => page.locator('nav[aria-label="Primary"]').getByRole('link', { name, exact: true }).click();
  const check = async (label, fn) => {
    try { await fn(); results[label] = 'ok'; } catch (e) { results[label] = 'FAILED ' + e.message.split('\n')[0].slice(0, 250); }
  };

  await page.goto(`${O}/detail/HO-001`, { waitUntil: 'networkidle' });
  await check('deploy files a mission', async () => {
    await page.getByRole('button', { name: 'Deploy', exact: true }).click();
    await page.getByText('Deployment order MS-109 filed').waitFor({ timeout: 3000 });
  });
  await check('missions screen lists the new deployment', async () => {
    await nav('Missions');
    await page.getByText('MS-109').first().waitFor({ timeout: 3000 });
  });
  await check('edit hero name saves and shows on roster and dashboard', async () => {
    await nav('Roster');
    await page.getByRole('link', { name: 'Edit Silverwing', exact: true }).click();
    await page.getByRole('button', { name: 'Edit', exact: true }).click();
    await page.locator('#hero-name').fill('Silverwing Prime');
    await page.getByRole('button', { name: 'Save', exact: true }).click();
    await page.getByText('Saved Silverwing Prime.').waitFor({ timeout: 3000 });
    await nav('Roster');
    await page.getByText('Silverwing Prime').first().waitFor({ timeout: 3000 });
    await nav('Dashboard');
    await page.getByText('Silverwing Prime').first().waitFor({ timeout: 3000 });
  });
  await check('recruit creates a hero and opens its dossier', async () => {
    await nav('Recruit');
    await page.locator('#recruit-name').fill('Test Recruit');
    await page.locator('#recruit-alias').fill('Test Alias');
    await page.locator('#recruit-power-index').fill('50');
    await page.locator('#recruit-clearance').fill('3');
    await page.getByRole('button', { name: 'Enlist hero' }).click();
    await page.waitForURL(/\/detail\/HO-013$/, { timeout: 3000 });
    await page.getByRole('heading', { name: 'Test Recruit', level: 1 }).waitFor({ timeout: 3000 });
  });
  await check('dashboard shows 13 heroes and the recruit', async () => {
    await nav('Dashboard');
    await page.getByText('13 heroes').waitFor({ timeout: 3000 });
    await page.getByRole('link', { name: 'Test Recruit', exact: true }).waitFor({ timeout: 3000 });
  });
  await check('theme switch toggles the dark class', async () => {
    await nav('Settings');
    const before = await page.evaluate(() => document.documentElement.classList.contains('dark'));
    await page.locator('#settings-dark').click();
    const after = await page.evaluate(() => document.documentElement.classList.contains('dark'));
    if (before === after) throw new Error('dark class did not change');
  });
  await check('retire removes the hero and returns to roster', async () => {
    await nav('Roster');
    await page.getByRole('link', { name: 'Edit Dr. Ion', exact: true }).click();
    await page.getByRole('button', { name: 'Retire', exact: true }).click();
    await page.getByRole('button', { name: 'Retire hero', exact: true }).click();
    await page.waitForURL(/\/roster$/, { timeout: 3000 });
    await page.getByRole('link', { name: 'Edit Dr. Ion', exact: true }).waitFor({ state: 'detached', timeout: 3000 });
  });
  await check('empty recruit submit does not navigate', async () => {
    await nav('Recruit');
    await page.getByRole('button', { name: 'Enlist hero' }).click();
    await page.waitForTimeout(300);
    if (!page.url().endsWith('/recruit')) throw new Error('navigated on empty submit: ' + page.url());
  });

  results['console errors'] = errors.length ? errors.slice(0, 10).join(' | ') : 'none';
} finally {
  await browser.close();
  await srv.close();
}
console.log(JSON.stringify(results, null, 2));

